package main

import (
	"errors"
	"fmt"
	"io/fs"
)

func open() error {
	return fmt.Errorf("open settings: %w", fs.ErrNotExist)
}

func load() error {
	if err := open(); err != nil {
		return fmt.Errorf("load config: %w", err)
	}
	return nil
}

func main() {
	err := load()
	fmt.Println(err)
	fmt.Println(errors.Is(err, fs.ErrNotExist))
}

